// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: blue; icon-glyph: images;
// Spray GenX Image Manager v4.0 UNIFIED SAFE
// Project-first image management with live GitHub re-fetch + verification.

const OWNER="MobsterGit",REPO="-spraygenx-website-public",BRANCH="main";
const GITHUB_TOKEN="token-here"; // paste your GitHub token here
const LIBRARY_PATH="data/image-library.json",CONVERTED_PATH="data/converted-images.json",INBOX_ROOT="images/inbox";
const api=p=>`https://api.github.com/repos/${OWNER}/${REPO}/contents/${p}`;
let SORT="az";
const today=()=>new Date().toISOString().slice(0,10);
const stamp=()=>new Date().toISOString().replace(/[-:T.Z]/g,"").slice(0,14);
const slug=v=>String(v||"project").toLowerCase().replace(/&/g,"and").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,80)||"project";
const csv=v=>String(v||"").split(",").map(x=>x.trim()).filter(Boolean);
const uniq=a=>[...new Set((a||[]).filter(Boolean))];
const pathOf=i=>typeof i==="string"?i:(i?.path||"");
const nameOf=p=>String(p||"").split("/").pop()||"image";
const clone=v=>JSON.parse(JSON.stringify(v));
const statusOf=b=>b.status||(b.visible===false?"hidden":"published");
const imgs=b=>Array.isArray(b.images)?b.images:[];
const cats=b=>uniq([b.category,...(Array.isArray(b.categories)?b.categories:[])]);
const norm=(i,t="")=>typeof i==="string"?{path:i,caption:"",alt:t||"Spray GenX project photo",visible:true,role:""}:{path:i?.path||"",caption:i?.caption||"",alt:i?.alt||i?.caption||t||"Spray GenX project photo",visible:i?.visible!==false,role:i?.role||""};
function b64(s){return Data.fromString(s).toBase64String()}
function decode(s){return Data.fromBase64String(String(s||"").replace(/\n/g,"")).toRawString()}
async function msg(t,m=""){let a=new Alert();a.title=t;a.message=m;a.addAction("OK");await a.presentAlert()}
async function pick(t,items,m=""){let a=new Alert();a.title=t;a.message=m;items.forEach(x=>x.d?a.addDestructiveAction(x.label):a.addAction(x.label));a.addCancelAction("Cancel");let n=await a.presentSheet();return n<0?null:items[n]}
async function ask(t,p,v=""){let a=new Alert();a.title=t;a.addTextField(p,v);a.addAction("OK");a.addCancelAction("Cancel");let n=await a.presentAlert();return n<0?null:a.textFieldValue(0).trim()}
async function fields(t,m,fs){let a=new Alert();a.title=t;a.message=m;fs.forEach(f=>a.addTextField(f[0],f[1]||""));a.addAction("Save");a.addCancelAction("Cancel");let n=await a.presentAlert();return n<0?null:fs.map((_,i)=>a.textFieldValue(i).trim())}
async function sure(t,m,y="Yes"){let a=new Alert();a.title=t;a.message=m;a.addDestructiveAction(y);a.addCancelAction("Cancel");return await a.presentAlert()===0}
async function gh(path,method="GET",body=null){if(!GITHUB_TOKEN||GITHUB_TOKEN==="token-here")throw Error("Paste your GitHub token into GITHUB_TOKEN first.");let r=new Request(api(path)+(method==="GET"?`?ref=${BRANCH}&_=${Date.now()}`:""));r.method=method;r.headers={Authorization:`Bearer ${GITHUB_TOKEN}`,Accept:"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28"};if(body){r.headers["Content-Type"]="application/json";r.body=JSON.stringify(body)}let j=await r.loadJSON();if(r.response.statusCode<200||r.response.statusCode>299)throw Error(`${method} ${path}\nHTTP ${r.response.statusCode}\n${JSON.stringify(j,null,2)}`);return j}
async function getJSON(path){let f=await gh(path);return{json:JSON.parse(decode(f.content)),sha:f.sha}}
async function lib(){let f=await getJSON(LIBRARY_PATH);if(!Array.isArray(f.json.blocks))throw Error("SAFETY STOP: live image library has no blocks array.");f.json.categories=Array.isArray(f.json.categories)?f.json.categories:[];return f}
async function putLib(x,sha,m){x.updated=today();return gh(LIBRARY_PATH,"PUT",{message:m,content:b64(JSON.stringify(x,null,2)+"\n"),sha,branch:BRANCH})}
async function putBin(path,data,m){return gh(path,"PUT",{message:m,content:data.toBase64String(),branch:BRANCH})}
async function mutate(id,m,fn,verify){let L=await lib(),count=L.json.blocks.length,i=L.json.blocks.findIndex(b=>b.id===id);if(i<0)throw Error("SAFETY STOP: project no longer exists.");let before=clone(L.json.blocks[i]),next=clone(before);await fn(next,L.json);if(next.id!==id||L.json.blocks.length!==count)throw Error("SAFETY STOP: unrelated project data changed.");L.json.blocks[i]=next;await putLib(L.json,L.sha,m);let C=await lib(),saved=C.json.blocks.find(b=>b.id===id);if(!saved||C.json.blocks.length!==count||verify&&!verify(saved,before))throw Error("VERIFY FAILED: GitHub read-back did not confirm the requested change.");return saved}
async function newProject(){let v=await fields("New Project","Create once; add images immediately.",[["Project title",""],["Description / summary","Completed Spray GenX project."],["Customer",""],["Location",""],["Tags, comma separated",""],["Weight / priority","25"]]);if(!v)return null;let L=await lib(),title=v[0]||"Untitled Project",id=`${slug(title)}-${stamp()}`,cat=L.json.categories[0]?.id||"uncategorized";let b={id,slug:slug(title),title,summary:v[1],customer:v[2],location:v[3],date:today(),category:cat,categories:[cat],tags:csv(v[4]),status:"draft",visible:true,weight:Number(v[5])||25,priority:Number(v[5])||25,views:{library:true,latest:true,search:true},siteLocations:["library","latest","search"],fallback:"latest",cover:"",images:[]};L.json.blocks.unshift(b);let n=L.json.blocks.length;await putLib(L.json,L.sha,`Create project: ${title}`);let C=await lib(),s=C.json.blocks.find(x=>x.id===id);if(!s||C.json.blocks.length!==n)throw Error("VERIFY FAILED: new project not confirmed.");return s}
function sorted(a){a=a.slice();if(SORT==="az")a.sort((x,y)=>(x.title||"").localeCompare(y.title||""));if(SORT==="za")a.sort((x,y)=>(y.title||"").localeCompare(x.title||""));if(SORT==="new")a.sort((x,y)=>(y.date||"").localeCompare(x.date||""));if(SORT==="old")a.sort((x,y)=>(x.date||"").localeCompare(y.date||""));return a}
async function selectProject(){let q="";while(true){let L=await lib(),a=sorted(L.json.blocks),shown=q?a.filter(b=>`${b.title} ${b.customer||""} ${b.location||""}`.toLowerCase().includes(q.toLowerCase())):a;let p=await pick("Projects",shown.map(b=>({label:`${b.title} · ${statusOf(b).toUpperCase()} · ${imgs(b).length} img`,id:b.id})).concat([{label:"⌕ Search",id:"search"},{label:`⇅ Sort (${SORT.toUpperCase()})`,id:"sort"},{label:"＋ New Project",id:"new"}]),q?`Filter: ${q}`:"Open a project; everything for it is here.");if(!p)return null;if(p.id==="search"){let x=await ask("Search Projects","Title, customer or location",q);if(x!==null)q=x;continue}if(p.id==="sort"){let x=await pick("Sort",[{label:"A–Z",id:"az"},{label:"Z–A",id:"za"},{label:"Newest",id:"new"},{label:"Oldest",id:"old"}]);if(x)SORT=x.id;continue}if(p.id==="new")return newProject();return L.json.blocks.find(b=>b.id===p.id)}}
async function editProject(b){let v=await fields("Edit Image Block","Everything for this project is managed from this project screen.",[["Project Title",b.title],["Description / Summary",b.summary||b.description||""],["Customer",b.customer||""],["Location",b.location||""],["Tags, comma separated",(b.tags||[]).join(", ")],["Weight / priority",String(b.weight??b.priority??25)]]);if(!v)return b;return mutate(b.id,`Edit project: ${v[0]}`,async n=>{n.title=v[0]||n.title;n.slug=slug(n.title);n.summary=v[1];n.customer=v[2];n.location=v[3];n.tags=csv(v[4]);n.weight=n.priority=Math.max(0,Math.min(100,Number(v[5])||25))},s=>s.title===(v[0]||b.title))}
async function chooseCategory(b){let L=await lib(),p=await pick("Change Category",L.json.categories.map(c=>({label:`${c.id===b.category?"✓ ":""}${c.label}`,id:c.id})).concat([{label:"＋ Add Category",id:"add"}]));if(!p)return b;if(p.id==="add"){let label=await ask("Add Category","Category name");if(!label)return b;let id=slug(label),F=await lib();if(!F.json.categories.some(c=>c.id===id))F.json.categories.push({id,label,sort:Math.max(0,...F.json.categories.map(c=>Number(c.sort)||0))+10});let x=F.json.blocks.find(x=>x.id===b.id);if(!x)throw Error("Project disappeared.");x.category=id;x.categories=uniq([id,...cats(x)]);await putLib(F.json,F.sha,`Add category: ${label}`);let C=await lib();if(!C.json.categories.some(c=>c.id===id))throw Error("VERIFY FAILED: category not saved.");return C.json.blocks.find(x=>x.id===b.id)}return mutate(b.id,`Change category: ${b.title}`,async n=>{n.category=p.id;n.categories=uniq([p.id,...cats(n)])},s=>s.category===p.id)}
async function jpeg(img,i){let fm=FileManager.local(),p=fm.joinPath(fm.temporaryDirectory(),`sgx-${stamp()}-${i}.jpg`);fm.writeImage(p,img);let d=fm.read(p);try{fm.remove(p)}catch{}return d}
async function attach(b,paths){return mutate(b.id,`Attach ${paths.length} image(s): ${b.title}`,async n=>{let have=new Set(imgs(n).map(pathOf));n.images=imgs(n).map(i=>norm(i,n.title));for(let p of paths)if(!have.has(p))n.images.push({path:p,caption:"",alt:n.title,visible:true,role:""});if(!n.cover&&n.images.length)n.cover=pathOf(n.images[0]);n.images.forEach(i=>i.role=pathOf(i)===n.cover?"cover":(i.role==="cover"?"":i.role))},s=>paths.every(p=>imgs(s).some(i=>pathOf(i)===p)))}
async function upload(b,arr){let paths=[];for(let i=0;i<arr.length;i++){let path=`${INBOX_ROOT}/${slug(b.slug||b.title)}/photo-${stamp()}-${String(i+1).padStart(2,"0")}.jpg`;await putBin(path,await jpeg(arr[i],i),`Upload photo: ${b.title}`);paths.push(path)}let s=await attach(b,paths);await msg("Upload Verified",`${paths.length} image(s) uploaded and attached to ${s.title}.\n\nGitHub read-back verified.`);return s}
async function addImages(b){let p=await pick("Add Images",[{label:"Upload One Photo",id:"one"},{label:"Upload Multiple Photos",id:"many"},{label:"Attach Converted Images",id:"converted"}],"Images attach to this exact project ID.");if(!p)return b;if(p.id==="one"){try{return upload(b,[await Photos.fromLibrary()])}catch{return b}}if(p.id==="many"){let a=[];while(a.length<24){try{a.push(await Photos.fromLibrary())}catch{break}let q=await pick("Add Images",[{label:"Add Another",id:"more"},{label:`Upload ${a.length} Selected`,id:"done"}]);if(!q||q.id==="done")break}return a.length?upload(b,a):b}let C;try{C=await getJSON(CONVERTED_PATH)}catch{await msg("No Converted Index","No converted image index was found.");return b}let L=await lib(),used=new Set();L.json.blocks.forEach(x=>imgs(x).forEach(i=>used.add(pathOf(i))));let avail=(C.json.images||[]).filter(x=>x.converted&&x.status!=="ignored"&&!used.has(x.converted)),chosen=[];while(avail.length){let q=await pick("Converted Images",avail.filter(x=>!chosen.includes(x.converted)).slice(0,40).map(x=>({label:nameOf(x.converted),path:x.converted})).concat([{label:`Attach Selected (${chosen.length})`,path:"done"}]));if(!q)return b;if(q.path==="done")break;chosen.push(q.path)}return chosen.length?attach(b,chosen):b}
async function preview(im){try{let r=new Request(`https://raw.githubusercontent.com/${OWNER}/${REPO}/${BRANCH}/${pathOf(im)}`);r.headers={Authorization:`Bearer ${GITHUB_TOKEN}`};await QuickLook.present(await r.loadImage(),true)}catch(e){await msg("Preview Failed",String(e.message||e))}}
async function imageAction(b,index){let im=norm(imgs(b)[index],b.title),p=await pick(nameOf(im.path),[{label:"Preview Image",id:"preview"},{label:"Edit Caption / Alt Text",id:"meta"},{label:im.path===b.cover?"✓ Cover Image":"Set as Cover Image",id:"cover"},{label:im.visible?"Hide Image":"Show Image",id:"visible"},{label:"Move Earlier",id:"up"},{label:"Move Later",id:"down"},{label:"Remove from Project",id:"remove",d:true}],`${index+1} of ${imgs(b).length}`);if(!p)return b;if(p.id==="preview"){await preview(im);return b}if(p.id==="meta"){let v=await fields("Image Details",nameOf(im.path),[["Caption",im.caption],["Alt text",im.alt]]);if(!v)return b;return mutate(b.id,`Edit image metadata: ${b.title}`,async n=>{n.images=imgs(n).map(i=>norm(i,n.title));let x=n.images.find(i=>pathOf(i)===im.path);if(!x)throw Error("Image changed before save.");x.caption=v[0];x.alt=v[1]||n.title},s=>imgs(s).some(i=>pathOf(i)===im.path&&norm(i).caption===v[0]))}if(p.id==="cover")return mutate(b.id,`Set cover: ${b.title}`,async n=>{n.cover=im.path;n.images=imgs(n).map(i=>{let x=norm(i,n.title);x.role=pathOf(x)===im.path?"cover":"";return x})},s=>s.cover===im.path);if(p.id==="visible")return mutate(b.id,`Toggle image: ${b.title}`,async n=>{n.images=imgs(n).map(i=>norm(i,n.title));let x=n.images.find(i=>pathOf(i)===im.path);x.visible=!im.visible},s=>true);if(p.id==="up"||p.id==="down")return mutate(b.id,`Reorder image: ${b.title}`,async n=>{n.images=imgs(n).map(i=>norm(i,n.title));let i=n.images.findIndex(x=>pathOf(x)===im.path),j=i+(p.id==="up"?-1:1);if(j>=0&&j<n.images.length)[n.images[i],n.images[j]]=[n.images[j],n.images[i]]},s=>true);if(p.id==="remove"&&await sure("Remove Image?",`Remove ${nameOf(im.path)} from this project?\n\nThe physical GitHub file will remain.`,"Remove"))return mutate(b.id,`Detach image: ${b.title}`,async n=>{n.images=imgs(n).filter(i=>pathOf(i)!==im.path);if(n.cover===im.path)n.cover=pathOf(n.images[0])||""},s=>!imgs(s).some(i=>pathOf(i)===im.path));return b}
async function manageImages(b){while(true){let L=await lib();b=L.json.blocks.find(x=>x.id===b.id)||b;let p=await pick("Project Images",imgs(b).map((i,n)=>({label:`${pathOf(i)===b.cover?"★ ":""}${norm(i).visible?"":"[hidden] "}${n+1}. ${nameOf(pathOf(i))}`,i:n})).concat([{label:"＋ Add Images",i:-2},{label:"Done",i:-1}]),`${b.title} · ${imgs(b).length} images`);if(!p||p.i===-1)return b;if(p.i===-2)b=await addImages(b);else b=await imageAction(b,p.i)}}
async function status(b){let p=await pick("Project Status",["draft","published","hidden","archived"].map(x=>({label:`${statusOf(b)===x?"✓ ":""}${x[0].toUpperCase()+x.slice(1)}`,id:x})));return p?mutate(b.id,`Status: ${b.title} → ${p.id}`,async n=>{n.status=p.id;n.visible=!['hidden','archived'].includes(p.id)},s=>statusOf(s)===p.id):b}
async function project(b){while(true){let L=await lib();b=L.json.blocks.find(x=>x.id===b.id);if(!b)return;let labels=cats(b).map(id=>L.json.categories.find(c=>c.id===id)?.label||id);let p=await pick("Edit Image Block",[{label:"＋ Add Images",id:"add"},{label:`Manage Images (${imgs(b).length})`,id:"images"},{label:"Edit Project Information",id:"edit"},{label:`Change / Add Category (${labels.length})`,id:"cat"},{label:`Status: ${statusOf(b).toUpperCase()}`,id:"status"},{label:"Preview Cover Image",id:"preview"},{label:"Save Draft",id:"draft"},{label:"Save & Publish",id:"publish"},{label:"Back to Projects",id:"back"}],`Everything for this project is on one page.\nCurrent status: ${statusOf(b).toUpperCase()} · ${imgs(b).length} images\n${b.customer||""}${b.location?" · "+b.location:""}\n${labels.join(", ")}`);if(!p||p.id==="back")return;if(p.id==="add")b=await addImages(b);if(p.id==="images")b=await manageImages(b);if(p.id==="edit")b=await editProject(b);if(p.id==="cat")b=await chooseCategory(b);if(p.id==="status")b=await status(b);if(p.id==="preview"){let i=imgs(b).find(i=>pathOf(i)===b.cover)||imgs(b)[0];i?await preview(i):await msg("No Images","Add an image first.")}if(p.id==="draft")b=await mutate(b.id,`Save draft: ${b.title}`,async n=>{n.status="draft";n.visible=true},s=>statusOf(s)==="draft");if(p.id==="publish")b=await mutate(b.id,`Publish: ${b.title}`,async n=>{n.status="published";n.visible=true},s=>statusOf(s)==="published")}}
async function counts(){let L=await lib();await msg("Counts",`Projects: ${L.json.blocks.length}\nPublished: ${L.json.blocks.filter(b=>statusOf(b)==="published").length}\nImages: ${L.json.blocks.reduce((n,b)=>n+imgs(b).length,0)}\nCategories: ${L.json.categories.length}`)}
async function main(){while(true){let p=await pick("Spray GenX Image Manager v4.0",[{label:"Projects — Open / Edit / Upload",id:"projects"},{label:"＋ New Project",id:"new"},{label:"Counts",id:"counts"},{label:"Done",id:"done"}],"Unified SAFE manager. Open a project and everything for that project is available there.");if(!p||p.id==="done")break;if(p.id==="projects"){let b=await selectProject();if(b)await project(b)}if(p.id==="new"){let b=await newProject();if(b)await project(b)}if(p.id==="counts")await counts()}}
main().catch(async e=>await msg("Image Manager Error",String(e.message||e)));
